import{n as r}from"./shared-CAKwAg2C.js";const n={"LEARN HOW THE INTERNET WORKS":"İNTERNET NASIL ÇALIŞIR","NOW LEARNING":"ŞU AN ÖĞRENİLEN","OSI LAYER":"OSI KATMANI","LEARNING PROGRESS":"İLERLEMENİZ",COMPLETE:"BİTTİ","IN PROGRESS":"SÜRÜYOR","{pct}% complete":"%{pct} tamamlandı","DESIGNED BY":"TASARLAYAN","Dilum Sanjaya on X":"Dilum Sanjaya, X’te","Layer {n}: {name}":"Katman {n}: {name}",Physical:"Fiziksel","Data Link":"Veri bağlantısı",Network:"Ağ",Transport:"Taşıma",Session:"Oturum",Presentation:"Sunum",Application:"Uygulama","OVERVIEW · {n} STEPS":"GENEL BAKIŞ · {n} ADIM","STEP {n}/{total} · {title}":"ADIM {n}/{total} · {title}","LESSON COMPLETE":"DERS TAMAMLANDI",PROTOCOLS:"PROTOKOLLER",Protocols:"Protokoller",Language:"Dil",Theme:"Tema","Light mode":"Açık mod","Dark mode":"Koyu mod","INTERNET PROTOCOLS":"İNTERNET PROTOKOLLERİ",More:"Daha fazla","Close the protocol list":"Protokol listesini kapat","Close (Esc)":"Kapat (Esc)",ALL:"TÜMÜ",CORE:"TEMEL",APPLICATION:"UYGULAMA",SECURITY:"GÜVENLİK",NETWORK:"AĞ",SEQUENCE:"SIRALAMA",View:"Görünüm","Switch view (V)":"Görünümü değiştir (V)","Network diagram":"Ağ diyagramı","Sequence diagram":"Sıralama diyagramı","STEP {n}":"ADIM {n}","PROTOCOL OVERVIEW":"GENEL BAKIŞ","STEP DETAILS":"GEÇERLİ ADIM","LESSON SUMMARY":"ÖZET",OVERVIEW:"BAŞA DÖN",ACTIVE:"AKTİF","STEP {n} OF {total}":"ADIM {n}/{total}","PACKET {n} OF {total}":"PAKET {n}/{total}","PACKETS {from}–{to} OF {total}":"PAKET {from}–{to}/{total}","{n} LOST":"{n} KAYIP","1 LOST":"1 KAYIP",ENCRYPTED:"ŞİFRELİ","LOST ON THE WAY":"YOLDA KAYBOLDU","PACKET FLOW":"PAKET AKIŞI","Colour key":"Renk açıklaması","Playback speed":"Oynatma hızı","Previous step (←)":"Önceki adım (←)","Previous step":"Önceki adım","Play / pause (Space)":"Oynat / duraklat (Boşluk)",PLAY:"OYNAT",PAUSE:"DURAKLAT",REPLAY:"TEKRARLA",STEP:"ADIM","One packet at a time":"Her seferinde bir paket",RESET:"SIFIRLA",Reset:"Sıfırla","Back to the overview (Esc)":"Genel bakışa dön (Esc)","NO.":"NO",TIME:"ZAMAN",SOURCE:"KAYNAK",DESTINATION:"HEDEF",PROTOCOL:"PROTOKOL",INFO:"BİLGİ",SIZE:"BOYUT","No packets on the wire yet.":"Henüz ağda paket yok.",LOST:"KAYIP","Packet inspector":"Paket inceleyici","Previous packet":"Önceki paket","Previous packet (←)":"Önceki paket (←)","Next packet":"Sonraki paket","Next packet (→)":"Sonraki paket (→)",Close:"Kapat","E.G.":"ÖRN.","an example value: it differs in every real capture":"örnek bir değer: her gerçek yakalamada farklıdır","bytes the lesson can’t show: encrypted, random, or a file’s contents":"dersin gösteremediği baytlar: şifreli, rastgele ya da bir dosyanın içeriği",BYTES:"BAYT","{n} in this frame":"bu çerçevede {n}","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Bu satır, {size} baytlık bir mesaj taşıyan {n} TCP segmentini temsil eder; ilk segment gösteriliyor","This packet was lost on the way":"Bu paket yolda kayboldu",Padding:"Dolgu","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · 24 SAAT KİRA","2 SEGMENTS":"2 SEGMENT","3 SEGMENTS":"3 SEGMENT","3 DATAGRAMS":"3 DATAGRAM","4 DATAGRAMS":"4 DATAGRAM","203.0.113.10 IS NOT LOCAL":"203.0.113.10 YEREL DEĞİL","250 QUEUED":"250 KUYRUKTA",ANSWER:"YANIT","APP COVERS THE 20 MS GAP":"UYGULAMA 20 MS’LİK BOŞLUĞU KAPATIR","APP DATA":"UYGULAMA VERİSİ","ARP REPLY":"ARP YANITI","ARP REQUEST":"ARP İSTEĞİ","ARRIVED WITH TTL 116":"TTL 116 İLE ULAŞTI","AUTH FAILURE":"AUTH BAŞARISIZ","At QUIT":"QUIT gelince","CACHED · TTL 3600 S":"ÖNBELLEKTE · TTL 3600 S","CERTIFICATE VALID":"SERTİFİKA GEÇERLİ","CHAIN LEADS TO A TRUSTED ROOT":"ZİNCİR GÜVENİLİR BİR KÖKE ULAŞIYOR","CHANNEL OPEN":"KANAL AÇ",CONFIRMED:"ONAYLANDI","DNS QUERY":"DNS SORGUSU","DNS REPLY":"DNS YANITI","DUP ACK":"YİNELENEN ACK","EACH KEY IS ITS OWN PACKET":"HER TUŞ AYRI BİR PAKET",ECHO:"YANKI","ECHO REPLY":"YANKI YANITI","ECHO REQUEST":"YANKI İSTEĞİ",ENTER:"ENTER","FRAME 7 LOST · NOT RESENT":"ÇERÇEVE 7 KAYIP · YENİDEN GÖNDERİLMEZ","HOP 2 · 198.51.100.1":"ATLAMA 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"SUNUCU ANAHTARI KNOWN_HOSTS İLE EŞLEŞİYOR","IN BOB’S MAILBOX":"BOB’UN POSTA KUTUSUNDA","IP PACKET":"IP PAKETİ",MESSAGE:"MESAJ","MESSAGE 1 DELETED":"MESAJ 1 SİLİNDİ","NEW MAIL ARRIVED":"YENİ POSTA GELDİ","NO IP ADDRESS YET":"HENÜZ IP ADRESİ YOK","NOT IN CACHE":"ÖNBELLEKTE YOK","OFFER KEY":"ANAHTAR ÖNER",OUTPUT:"ÇIKTI","PASSWORD IN PLAIN TEXT":"PAROLA DÜZ METİN",REFERRAL:"YÖNLENDİRME",REPLY:"YANIT",RESEND:"YENİDEN GÖNDER","SEGMENT 1 LOST":"SEGMENT 1 KAYIP","SFTP or FTPS":"SFTP veya FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP veya FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"ORTAK SIR HESAPLANDI",SIGNED:"İMZALANDI","STILL ON SERVER · \\SEEN":"HÂLÂ SUNUCUDA · \\SEEN",SUCCESS:"BAŞARILI","TIME EXCEEDED":"SÜRE AŞILDI","TIME=34MS TTL=52":"SÜRE=34MS TTL=52",UNREACHABLE:"ULAŞILAMIYOR",VERSION:"SÜRÜM","VOICE 1":"SES 1","+OK or -ERR":"+OK veya -ERR",".com Server":".com sunucusu",Authoritative:"Yetkili","Log In":"Oturum aç",Key:"Anahtar",Why:"Neden",End:"Son","MACs, in":"MAC’ler, giriş",Internet:"İnternet",Router:"Yönlendirici","Router 192.168.1.1":"Yönlendirici 192.168.1.1","Router: 192.168.1.1":"Yönlendirici: 192.168.1.1",Routers:"Yönlendiriciler",Hardware:"Donanım",Audio:"Ses",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic cookie",Visible:"Görünen",Tickets:"Biletler","4, 20 bytes":"4, 20 bayt","20–60 bytes":"20–60 bayt","20–60 bytes (IPv4)":"20–60 bayt (IPv4)","8 bytes (TCP: 20+)":"8 bayt (TCP: 20+)","32 bytes (Windows)":"32 bayt (Windows)","1,460 bytes (MSS)":"1,460 bayt (MSS)","78 bytes (seq 1–78)":"78 bayt (seq 1–78)","bytes 1461–2920":"bayt 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 bayt)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 bayt)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 bayt), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 bayt)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 bayt)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 bayt)',"32 bits (IPv4), 128 (IPv6)":"32 bit (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 → 52 (12 yönlendirici)","52 (64 − 12 routers)":"52 (64 − 12 yönlendirici)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 bayt","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 bayt (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + ses"},i={"Hypertext Transfer Protocol":"Hiper metin aktarımı","HTTP Secure":"Güvenli HTTP","Transmission Control Protocol":"İletim denetim protokolü","User Datagram Protocol":"Kullanıcı datagram protokolü","Internet Protocol":"İnternet protokolü","Domain Name System":"Alan adı sistemi","Dynamic Host Configuration":"Dinamik host yapılandırması","Internet Control Message":"İnternet denetim mesajları","Simple Mail Transfer Protocol":"Basit posta aktarım protokolü","Post Office Protocol v3":"Postane protokolü v3","Internet Message Access":"İnternet mesaj erişimi","File Transfer Protocol":"Dosya aktarım protokolü","Secure Shell":"Güvenli kabuk","Transport Layer Security":"Taşıma katmanı güvenliği",Internet:"İnternet",Client:"İstemci",Router:"Yönlendirici","DNS Resolver":"DNS çözümleyici","Web Server":"Web sunucusu","Root Server":"Kök sunucu",".com TLD Server":".com TLD sunucusu","Authoritative Server":"Yetkili sunucu","Mail Server":"Posta sunucusu","Web Communication":"Web iletişimi",Request:"İstek",Response:"Yanıt","Data ACKs not shown":"Veri onayları (ACK) gösterilmiyor","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP, web’in protokolüdür: bir istemci HTML sayfası gibi bir kaynak ister, sunucu da bir durum kodu, başlıklar ve genellikle bir gövdeyle yanıt verir. Her alışveriş bir istek ve bir yanıttan oluşur; HTTP/1.1’de bunlar okunabilir metin olarak yazılır.",Layer:"Katman","Application (Layer 7)":"Uygulama (7. katman)","Default Port":"Varsayılan port",Transport:"Taşıma","Data Format":"Veri biçimi","Text (headers + optional body)":"Metin (başlıklar + isteğe bağlı gövde)","Common Methods":"Yaygın yöntemler","Defined In":"Tanımlandığı belge","Page delivered":"Sayfa teslim edildi","One request, one response":"Bir istek, bir yanıt","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"Dizüstü bilgisayar, saniyenin onda birinden kısa sürede bir adres sorguladı, bir TCP bağlantısı açtı ve bir HTTP isteğiyle yanıtını alıp verdi; hepsi yoldaki herkesin okuyabileceği biçimde. Yeniden izlemek için TEKRARLA’ya basın.","Round trips":"Gidiş-dönüşler","Total time":"Toplam süre","Page size":"Sayfa boyutu","Sent as 9 TCP segments":"9 TCP segmentiyle gönderildi","Client Request":"İstemci isteği","Browser prepares the request":"Tarayıcı isteği hazırlar","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"http://www.example.com adresini açıyorsunuz. Tarayıcı bir GET isteği gönderecek, ancak paketler adlara değil IP adreslerine gider; bu yüzden önce sunucunun adresine ihtiyacı var. (Tarayıcılar artık önce https:// dener; bu, şifresiz sürüm.)",Method:"Yöntem","Next hop":"Sonraki atlama","Router 192.168.1.1":"Yönlendirici 192.168.1.1","DNS Resolution":"DNS çözümleme","Finds the server’s IP address":"Sunucunun IP adresini bulur","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"Dizüstü, DHCP’den aldığı DNS sunucusuna (8.8.8.8) www.example.com adresini sorar. Sorgu UDP üzerinden 53 numaralı porta gider ve yanıt, IPv4 adresini içeren bir A kaydıdır. (IPv6 olan bir ağda bir AAAA kaydı da isterdi.)",Resolver:"Çözümleyici","8.8.8.8 (had it cached)":"8.8.8.8 (önbelleğinde vardı)","UDP, port 53":"UDP, port 53",Answer:"Yanıt","TCP Connection":"TCP bağlantısı","Establishes a reliable link":"Güvenilir bir bağlantı kurar","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP, TCP’nin üzerinde çalışır. Sayfaya ait herhangi bir veri gitmeden önce dizüstü ile sunucu, üç yönlü el sıkışmayla 80 numaralı porta bir bağlantı açar: SYN, SYN-ACK, ACK.","Server port":"Sunucu portu","Client port":"İstemci portu",Handshake:"El sıkışma","HTTP Exchange":"HTTP alışverişi","Request and response messages":"İstek ve yanıt mesajları","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Tarayıcı, Host başlığı içeren bir GET isteği gönderir. Sunucu 200 OK ile yanıt verir ve HTML’yi gövdede yollar: 12.2 KB, tek bir paket için fazla büyük, bu yüzden TCP onu en fazla 1460 baytlık 9 segmente böler (burada tek parça çizildi).",Status:"Durum",Body:"Gövde","Sent as":"Gönderim","12.2 KB in 9 segments":"9 segmentte 12.2 KB","Page Rendering":"Sayfanın oluşturulması","Browser displays the content":"Tarayıcı içeriği gösterir","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Tarayıcı HTML’yi ayrıştırır ve sayfayı çizer. Bağlantılı CSS, görsel ve betiklerin her biri bunun gibi yeni istekler başlatır ve mümkün olduğunda açık bağlantıyı yeniden kullanır.",Document:"Belge",Connection:"Bağlantı","Kept open for reuse":"Yeniden kullanım için açık tutuldu","Seen on the laptop’s home network":"Dizüstünün ev ağında görüldü",Destination:"Hedef","The router: anything beyond the home network goes to it first.":"Yönlendirici: ev ağının dışına giden her şey önce ona gider.",Source:"Kaynak","The laptop’s network card.":"Dizüstünün ağ kartı.",Type:"Tür","What the frame carries.":"Çerçevenin taşıdığı şey.","Version, header length":"Sürüm, başlık uzunluğu","IPv4, with no options.":"IPv4, seçeneksiz.","Priority and congestion marks; 0 means ordinary traffic.":"Öncelik ve tıkanıklık işaretleri; 0 sıradan trafik demektir.","Total length":"Toplam uzunluk","This header and everything inside it.":"Bu başlık ve içindeki her şey.",Identification:"Kimlik","Lets the receiver reassemble the pieces if the packet gets split.":"Paket bölünürse alıcının parçaları yeniden birleştirmesini sağlar.",Flags:"Bayraklar",none:"yok","Routers may split it if a link is too small.":"Bir bağlantı çok küçükse yönlendiriciler onu bölebilir.","Time to live":"Yaşam süresi","Windows starts at 128.":"Windows 128’den başlar.",Protocol:"Protokol","Header checksum":"Başlık sağlama toplamı","Covers this header only; every router recomputes it after lowering the TTL.":"Yalnızca bu başlığı kapsar; her yönlendirici TTL’yi düşürdükten sonra onu yeniden hesaplar.","Source port":"Kaynak port","Destination port":"Hedef port",Length:"Uzunluk","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"UDP başlığı ve veri. UDP’nin hepsi bu: numaralandırma yok, onay yok.",Checksum:"Sağlama toplamı","Covers the header, the data and the IP addresses.":"Başlığı, veriyi ve IP adreslerini kapsar.","Transaction ID":"İşlem kimliği","Picked at random; the answer must carry the same one.":"Rastgele seçilir; yanıt da aynısını taşımalıdır.","0x0100: query, RD (recursion desired)":"0x0100: sorgu, RD (özyineleme isteniyor)",Questions:"Sorular",Answers:"Yanıtlar","Authority records":"Yetki kayıtları","Additional records":"Ek kayıtlar",Question:"Soru","www.example.com, type A, class IN":"www.example.com, tür A, sınıf IN","The laptop.":"Dizüstü bilgisayar.","The router’s side facing the home network.":"Yönlendiricinin ev ağına bakan tarafı.","Started at 128; 10 routers on the way each took 1.":"128’den başladı; yoldaki 10 yönlendiricinin her biri 1 düşürdü.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: yanıt, RD (özyineleme isteniyor), RA (özyineleme mevcut)","DF (don’t fragment)":"DF (parçalama)","Routers must not split it; if it’s too big they report back instead.":"Yönlendiriciler onu bölmemelidir; çok büyükse bunun yerine geri bildirirler.","Picked by the laptop’s system for this connection.":"Bu bağlantı için dizüstünün sistemi tarafından seçildi.","Sequence number":"Sıra numarası","This side’s starting number. Shown as 0; the real one is random.":"Bu tarafın başlangıç numarası. 0 olarak gösterilir; gerçeği rastgeledir.","Real sequence number":"Gerçek sıra numarası",Acknowledgment:"Onay","0 (not used yet)":"0 (henüz kullanılmıyor)","A first SYN has nothing to acknowledge.":"İlk SYN’in onaylayacağı bir şey yoktur.","Header length":"Başlık uzunluğu","20 bytes, plus 12 of options.":"20 bayt, artı 12 bayt seçenek.",Window:"Pencere","How much more data this side can take right now.":"Bu tarafın şu anda daha ne kadar veri alabileceği.","Covers the header, the data and the IP addresses, so damage is caught.":"Başlığı, veriyi ve IP adreslerini kapsar; böylece bozulma yakalanır.","Urgent pointer":"Acil işaretçisi",Options:"Seçenekler","Maximum segment size":"Azami segment boyutu","The most data this side wants in one segment.":"Bu tarafın tek bir segmentte istediği en fazla veri.","Spacing, so the next option lines up.":"Bir sonraki seçenek hizalansın diye boşluk.","Window scale":"Pencere ölçeği","Window values are multiplied by this, so windows can be larger than 64 KB.":"Pencere değerleri bununla çarpılır; böylece pencereler 64 KB’tan büyük olabilir.","SACK permitted":"SACK izinli",yes:"evet","This side understands selective acknowledgements.":"Bu taraf seçici onayları anlar.","Started at 64; 12 routers on the way each took 1.":"64’ten başladı; yoldaki 12 yönlendiricinin her biri 1 düşürdü.","The next byte this side expects: everything before it has arrived.":"Bu tarafın beklediği sonraki bayt: ondan öncekilerin hepsi geldi.","Position of this segment’s first byte, counted from this side’s SYN.":"Bu segmentin ilk baytının konumu; bu tarafın SYN’inden itibaren sayılır.",Padding:"Dolgu","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Ethernet çerçeveleri en az 60 bayttır (kartın eklediği sağlama toplamıyla 64), bu yüzden kısa olanlar doldurulur.",Text:"Metin","covers bytes not shown here":"burada gösterilmeyen baytları kapsar","12,500 bytes: the HTML page":"12,500 bayt: HTML sayfası","The page itself; its contents are not part of the lesson.":"Sayfanın kendisi; içeriği dersin parçası değil.","Secure Web":"Güvenli web","TLS handshake":"TLS el sıkışması","HTTP request":"HTTP isteği","HTTP response":"HTTP yanıtı","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS, şifreli bir TLS bağlantısı üzerinden gönderilen HTTP’dir. TLS, bir sertifikayla sunucunun gerçekten iddia ettiği sunucu olduğunu kanıtlar, yeni şifreleme anahtarları üzerinde anlaşır ve ardından her isteği ve yanıtı yolda okunmaya ya da değiştirilmeye karşı korur.","Application (HTTP over TLS)":"Uygulama (TLS üzerinden HTTP)",Security:"Güvenlik","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 hâlâ yaygın)",Proves:"Kanıtladığı","Server identity (certificate)":"Sunucu kimliği (sertifika)","Secure page delivered":"Güvenli sayfa teslim edildi","Encrypted, except the lookup":"DNS sorgusu dışında şifreli","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Tarayıcı adresi şifresiz DNS ile sorguladı, bir TCP bağlantısı açtı, sunucunun sertifikasını doğruladı ve anahtarlarda tek bir gidiş-dönüşte anlaştı. Bundan sonraki her HTTP baytı şifreli gitti. Yeniden izlemek için TEKRARLA’ya basın.",Cipher:"Şifre takımı","Still visible":"Hâlâ görünen","IPs, server name, sizes":"IP adresleri, sunucu adı, boyutlar","Secure Request":"Güvenli istek","Browser asks for https://":"Tarayıcı https:// ister","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"https://www.example.com yazıyorsunuz. “s” harfi tarayıcıya bağlantıyı TLS ile korumasını söyler; varsayılan port 443’tür. Bağlanabilmek için yine de önce sunucunun IP adresini bulması gerekir.",Port:"Port","DNS Lookup":"DNS sorgusu","Same lookup as HTTP, not encrypted":"HTTP’dekiyle aynı sorgu, şifresiz","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"Sorgu, düz HTTP’dekiyle tamamen aynıdır: UDP üzerinden 53 numaralı porta, 8.8.8.8 adresine giden bir sorgu. Şifreli değildir; bu yüzden tarayıcı DNS over HTTPS kullanmıyorsa yoldaki herkes hangi adı sorduğunuzu görebilir.",Encrypted:"Şifreli","No (plain DNS)":"Hayır (düz DNS)","TCP Handshake":"TCP el sıkışması","Opens a connection to port 443":"443 numaralı porta bağlantı açar","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS, TCP üzerinde çalışır; bu yüzden önce aynı üç yönlü el sıkışma gelir, bu kez 443 numaralı porta. Henüz hiçbir şey şifreli değildir.","TLS Handshake":"TLS el sıkışması","Agrees on keys, checks the certificate":"Anahtarlarda anlaşır, sertifikayı doğrular","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Tarayıcı şifre takımları ve anahtar payları önerir; aralarında kuantum sonrası bir hibrit de vardır. Sunucu onu seçer ve kendi payını, ardından zaten şifrelenmiş sertifikasını gönderir. Tarayıcı sertifikayı güvendiği otoritelere göre doğrular.",Version:"Sürüm","Key exchange":"Anahtar değişimi","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (hibrit)","Server name":"Sunucu adı","Sent in clear (SNI)":"Açık metin olarak gönderilir (SNI)","key shares: hybrid + x25519":"anahtar payları: hibrit + x25519","cipher: AES_128_GCM_SHA256":"şifre takımı: AES_128_GCM_SHA256","then encrypted: cert, Finished":"sonra şifreli: sertifika, Finished","handshake complete (encrypted)":"el sıkışma tamam (şifreli)","Encrypted Exchange":"Şifreli alışveriş","HTTP inside TLS records":"TLS kayıtları içinde HTTP","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"GET ve 200 OK, öncekiyle aynı HTTP mesajlarıdır; ağda rastgele “uygulama verisi” gibi görünen TLS kayıtlarına mühürlenmişlerdir. Sunucu ayrıca iki oturum bileti verir; böylece sonraki bir ziyaret el sıkışmanın bir kısmını atlayabilir.",Inside:"İçeride","GET / and 200 OK":"GET / ve 200 OK",Tickets:"Biletler","2, for faster reconnects":"2, daha hızlı yeniden bağlanmak için","inside: GET / HTTP/1.1":"içeride: GET / HTTP/1.1","outside: encrypted bytes":"dışarıda: şifreli baytlar","inside: HTTP/1.1 200 OK":"içeride: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"dışarıda: 12.9 KB, 9 segment","Browser shows the padlock":"Tarayıcı kilidi gösterir","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Tarayıcı yanıtın şifresini çözer, sayfayı çizer ve bir kilit simgesi gösterir: bağlantı gizlidir ve sunucu kimliğini kanıtlamıştır. Strict-Transport-Security başlığı ona bu sitede bundan sonra HTTPS kullanmasını söyler.",Remembers:"Hatırladığı","HTTPS only (HSTS), 1 year":"Yalnızca HTTPS (HSTS), 1 yıl","Server Hello + encrypted handshake, 3 segments":"Server Hello + şifreli el sıkışma, 3 segment","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (şifreli)","Application Data (HTTP request)":"Application Data (HTTP isteği)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (şifreli)","Application Data (HTTP response), 9 segments":"Application Data (HTTP yanıtı), 9 segment",Record:"Kayıt","Content type":"İçerik türü","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"Bir Client Hello’nun kaydında TLS 1.0 yazar ki eski ara cihazlar onu geçirsin; gerçek sürümler içeride önerilir.","Handshake type":"El sıkışma türü",Contents:"İçerik","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Tarayıcının desteklediği her şey. Tarayıcılar bazı ayrıntıları bağlantıdan bağlantıya değiştirir.","Server name (SNI)":"Sunucu adı (SNI)","Versions offered":"Önerilen sürümler","Key shares":"Anahtar payları","App protocols (ALPN)":"Uygulama protokolleri (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"TLS 1.3 kayıtlarının dışında, uyumluluk için 1.2 yazar.","The server’s choices and its half of the hybrid key exchange.":"Sunucunun seçimleri ve hibrit anahtar değişiminde ona düşen yarı.","Cipher suite":"Şifre takımı","Key share":"Anahtar payı","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"TLS 1.3’te hiçbir işlevi yoktur; ara cihazlar tanıdık bir el sıkışma görsün diye gönderilir.","Every encrypted record says Application Data on the outside; the real type is inside.":"Her şifreli kaydın dışında Application Data yazar; gerçek tür içeridedir.","Encrypted data":"Şifreli veri","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Şifreli metin; sonunda her değişikliği ele veren 16 baytlık bir etiket bulunur. Onu yalnızca iki uç okuyabilir.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (zincir), Certificate Verify (imza), Finished","Finished: a check value over the whole handshake":"Finished: tüm el sıkışma üzerinden bir doğrulama değeri","The HTTP request":"HTTP isteği","New Session Ticket: lets a later visit resume":"New Session Ticket: sonraki bir ziyaretin oturumu sürdürmesini sağlar","The HTTP response, then the 12,500-byte page":"HTTP yanıtı, ardından 12,500 baytlık sayfa","Reliable Delivery":"Güvenilir teslimat","Handshake and ACKs":"El sıkışma ve onaylar","Data from laptop":"Dizüstünden gelen veri","Data from server":"Sunucudan gelen veri","Closing (FIN)":"Kapanış (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP, internetin “en iyi çaba” esaslı paket teslimatını güvenilir ve sıralı bir bayt akışına dönüştürür. Her baytı numaralar, geleni onaylar, kaybolanı yeniden gönderir ve göndericinin hızını ayarlar; böylece ne karşı taraf ne de ağ boğulur.","Transport (Layer 4)":"Taşıma (4. katman)","Three-way handshake":"Üç yönlü el sıkışma",Reliability:"Güvenilirlik","Sequence numbers + ACKs":"Sıra numaraları + ACK",Recovery:"Kurtarma",Retransmission:"Yeniden iletim",Header:"Başlık","Connection closed":"Bağlantı kapandı","Every byte accounted for":"Her bayt hesapta","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP bir bağlantı açtı, her baytı numaralayıp onayladı, bir boşluk fark edip yalnızca eksik segmenti yeniden gönderdi, sonra iki yönü de temiz biçimde kapattı. curl her baytı sırayla aldı ve kaybı hiç görmedi. Yeniden izlemek için TEKRARLA’ya basın.",Segments:"Segmentler","14 (1 lost, 1 resent)":"14 (1 kayıp, 1 yeniden gönderildi)","Bytes delivered":"Teslim edilen baytlar","78 up, 2,920 down":"78 giden, 2,920 gelen","Loss found by":"Kaybı bulan","Duplicate ACK + SACK":"Yinelenen ACK + SACK","Open Connection":"Bağlantıyı aç","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl sunucunun adresini zaten biliyor. Herhangi bir veri gitmeden önce iki taraf da bir başlangıç sıra numarası seçer ve onaylar: SYN, SYN-ACK, ACK. Buradaki numaralar görelidir; gerçekleri rastgele bir değerden başlar.",Server:"Sunucu","203.0.113.10, port 80":"203.0.113.10, port 80","Send Data":"Veri gönder","Every byte is numbered":"Her bayt numaralanır","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl, 78 baytlık HTTP isteğini gönderir: 1’den 78’e kadar olan baytlar. Sunucunun ACK numarası olan 79, beklediği sonraki bayttır; yani ondan öncekilerin hepsi gelmiştir.",Sent:"Gönderilen","79 = next byte expected":"79 = beklenen sonraki bayt","Two Segments Back":"Geri dönen iki segment","One of them is lost":"Biri kaybolur","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Sunucu 2,920 baytla yanıt verir: 1,460’ar baytlık, yani burada bir pakete sığabilecek en fazla miktarda iki dolu segment, art arda gönderilir. İlki internette bir yerde düşer; ikincisi ulaşır.","Segment 1":"Segment 1","bytes 1–1460 (lost)":"bayt 1–1460 (kayıp)","Segment 2":"Segment 2","Segment size":"Segment boyutu","seq=1 and seq=1461":"seq=1 ve seq=1461","the first is lost":"ilki kaybolur","A Gap Is Noticed":"Bir boşluk fark edilir","Duplicate ACK with SACK":"SACK içeren yinelenen ACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"1461–2920 baytları gelir, ama 1–1460 hiç gelmez. Bir ACK yalnızca sırayla alınan baytları sayabilir; bu yüzden dizüstü ACK 1’i hemen tekrarlar ve 1461–2920’yi zaten aldığını söyleyen bir SACK bloğu ekler.","1 (still waiting for byte 1)":"1 (hâlâ 1. baytı bekliyor)","holds bytes 1461–2920":"1461–2920 baytları elinde","At once, not delayed":"Hemen, gecikmeden","sack: has 1461–2920":"sack: elinde 1461–2920","Resend the Gap":"Boşluğu yeniden gönder","Only the missing bytes":"Yalnızca eksik baytlar","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"SACK sunucuya neyin eksik olduğunu tam olarak söyler; bu yüzden sunucu yalnızca 1. segmenti yeniden gönderir ve dizüstü her şeyi onaylar. Hiç ACK gelmeseydi zamanlayıcılar devreye girerdi: önce yaklaşık iki gidiş-dönüş sonra bir yoklama, ardından yeniden iletim zaman aşımı (Linux’ta en az 200 ms).",Resent:"Yeniden gönderilen","bytes 1–1460 only":"yalnızca bayt 1–1460","Next ACK":"Sonraki ACK","2921 (everything)":"2921 (hepsi)","curl saw":"curl’ün gördüğü","Every byte, in order":"Her bayt, sırayla","just the missing segment":"yalnızca eksik segment","Close Connection":"Bağlantıyı kapat","Each side says goodbye":"Her taraf veda eder","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl işini bitirdi, bu yüzden kapatır. Her yön kendi başına kapanır: dizüstü FIN gönderir ve sunucu onaylar, ardından sunucu kendi FIN’ini gönderir ve dizüstü onu onaylar. Dizüstü bağlantının ayrıntılarını bir süre saklar (TIME-WAIT).","Closed by":"Kapatan","A FIN from each side":"Her taraftan bir FIN",Order:"Sıra",Then:"Sonra","Laptop waits (TIME-WAIT)":"Dizüstü bekler (TIME-WAIT)",Data:"Veri","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 bayt: HTTP yanıtı, bayt 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 bayt: HTTP yanıtı, bayt 1461–2920","has 1461–2920":"elinde 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Boşluktan sonra gelen baytlar; bu yüzden yalnızca boşluğun yeniden gönderilmesi gerekir.","Fast Datagrams":"Hızlı datagramlar","Your voice":"Sizin sesiniz","Their voice":"Karşı tarafın sesi","Media Server":"Medya sunucusu","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP, verileri datagram adı verilen bağımsız paketlerle gönderir; bağlantı, onay ve yeniden gönderim yoktur. Bu onu hızlı ve hafif tutar: geç gelen bir yanıtın hiç gelmeyenden daha kötü olduğu ses, görüntü, oyun ve DNS için doğru seçimdir.",None:"Yok","None (no ACKs, no resends)":"Yok (ACK yok, yeniden gönderim yok)",Ordering:"Sıra","Not guaranteed":"Garanti edilmez","Call keeps flowing":"Görüşme akmaya devam ediyor","Fast, simple, no guarantees":"Hızlı, basit, garantisiz","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"Ses daha ilk paketle başladı, her datagram kendi başına yol aldı ve kaybolan datagram öylece gitti: UDP bunu hiç fark etmedi. Uygulama boşluğu kapattı ve görüşme sürdü. Yeniden izlemek için TEKRARLA’ya basın.",Datagrams:"Datagramlar","11 (1 lost, never resent)":"11 (1’i kayboldu, hiç yeniden gönderilmedi)","Setup time":"Kurulum süresi","0 ms (no handshake)":"0 ms (el sıkışma yok)",Shown:"Gösterilen","The first 0.2 s of a call":"Bir görüşmenin ilk 0.2 saniyesi","Send Right Away":"Hemen gönder","No handshake, data goes first":"El sıkışma yok, önce veri gider","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Bir arama uygulaması, medya sunucusunun adresini ve portunu oturum açarken zaten öğrenmiştir. Bağlantı açmaz: daha ilk datagram, 8 baytlık bir UDP başlığının arkasında sesinizin 20 ms’sini taşır.",Setup:"Kurulum",Ports:"Portlar","92 B of audio, no setup":"92 B ses, kurulum yok","A Stream of Datagrams":"Bir datagram akışı","One every 20 ms, each on its own":"Her 20 ms’de bir, her biri kendi başına","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"Uygulama her 20 ms’de bir datagram göndermeye devam eder. Her biri tek başına durur; kendi başlığı vardır ve diğerleriyle bağı yoktur. UDP onları numaralandırmaz ve ulaştıklarını doğrulamak için geri hiçbir şey gelmez.",Rate:"Sıklık","1 datagram / 20 ms":"1 datagram / 20 ms",Numbering:"Numaralandırma","None in UDP itself":"UDP’nin kendisinde yok",Confirmation:"Onay","None (no ACKs)":"Yok (ACK yok)","voice frames 2–5":"ses çerçeveleri 2–5","each with its own 8-byte header":"her biri kendi 8 baytlık başlığıyla","Lost on the Way":"Yolda kayboldu","Nobody resends it":"Kimse yeniden göndermez","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"Çerçeve 7, internette bir yerde düşer. Medya sunucusu onu hiç istemez ve UDP dizüstüne hiç haber vermez: eksikliği fark edilecek onaylar yoktur. Ondan sonraki datagramlar normal şekilde ulaşır.",Lost:"Kayıp","Voice frame 7":"Ses çerçevesi 7","Never (no ACKs)":"Asla (ACK yok)",Missing:"Eksik","20 ms of audio":"20 ms ses","voice frames 6–8":"ses çerçeveleri 6–8","frame 7 is lost":"çerçeve 7 kaybolur","Replies Come Back":"Yanıtlar geri gelir","The other voice comes back":"Diğer ses geri gelir","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"Karşıdaki kişinin sesi de aynı şekilde, 50000 numaralı porta gönderilen ayrı datagramlar olarak gelir. İçeri girebilirler, çünkü yönlendiriciniz adresinizi çevirirken (NAT) giden portu hatırlamıştır.",Direction:"Yön","Independent of ours":"Bizimkinden bağımsız","Through NAT":"NAT üzerinden","Router remembers the port":"Yönlendirici portu hatırlar","the other person’s voice":"karşıdaki kişinin sesi","sent to port 50000":"50000 numaralı porta gönderilir","The App Decides":"Uygulama karar verir","Reliability is up to the app":"Güvenilirlik uygulamaya kalmış","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"Arama uygulaması kendi çerçevelerini numaralandırır (bunu RTP yapar), böylece çerçeve 7’nin eksik olduğunu görür ve beklemek yerine 20 ms’lik boşluğu yumuşatır. Yeniden gönderimi beklemek tüm görüşmeyi geciktirirdi.","App’s job (e.g. RTP)":"Uygulamanın işi (ör. RTP)",Loss:"Kayıp","Hidden by the app":"Uygulama tarafından gizlenir","Also on UDP":"UDP’yi kullanan diğerleri","DNS, games, QUIC":"DNS, oyunlar, QUIC","Version etc.":"Sürüm vb.","2, no padding, no extension, no CSRCs":"2, dolgu yok, uzantı yok, CSRC yok","Marker, payload type":"İşaretçi, yük türü","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, görüşme kurulurken kararlaştırıldı)","Counts up by one per packet, so the app can spot a missing or late one.":"Her pakette bir artar; böylece uygulama eksik ya da geciken bir paketi fark edebilir.",Timestamp:"Zaman damgası","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Saniyede 48,000 adım ilerleyen ses saati: 20 ms’lik her çerçevede +960.","Identifies this audio stream.":"Bu ses akışını tanımlar.",Audio:"Ses","80 bytes of Opus audio (20 ms)":"80 bayt Opus ses (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, görüşme kurulurken kararlaştırıldı)","Addressing & Routing":"Adresleme ve yönlendirme","Outgoing packet":"Giden paket",Reply:"Yanıt","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP her cihaza bir adres verir ve paketleri ağdan ağa taşır. Her yönlendirici bir sonraki atlamayı seçmek için yalnızca hedef adrese bakar. IP “en iyi çaba” ile çalışır: teslimat ya da sıra sözü vermez. Bunları üstüne TCP ekler.","Network (Layer 3)":"Ağ (3. katman)",Address:"Adres","Lowered by 1 at each router":"Her yönlendiricide 1 azalır",Delivery:"Teslimat","Best effort":"En iyi çaba","There and back":"Gidiş ve dönüş","Twelve routers each way":"Her yönde on iki yönlendirici","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"Dizüstü paketi kendi yönlendiricisine gönderdi; yönlendirici de kendi genel adresini yerleştirdi. Toplam on iki yönlendirici onu yalnızca hedef adrese bakarak iletti ve yanıt da aynı şekilde geri yolunu buldu. Yeniden izlemek için TEKRARLA’ya basın.",Routers:"Yönlendiriciler","12 each way (1 home + 11)":"Her yönde 12 (1 ev + 11)","TTL at server":"Sunucudaki TTL","116 (sent with 128)":"116 (128 ile gönderildi)","Rewritten by NAT":"NAT tarafından yeniden yazılır","Source out, destination back":"Gidişte kaynak, dönüşte hedef","IPv4 (IPv6 works alike)":"IPv4 (IPv6 da aynı şekilde çalışır)","Local or Not?":"Yerel mi, değil mi?","Compare the address with the subnet":"Adresi alt ağla karşılaştır","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"Dizüstünün adresi /24 maskeyle 192.168.1.10’dur, yani kendi ağı 192.168.1.0 ile 192.168.1.255 arasıdır. Sunucu, 203.0.113.10, bu aralığın dışındadır; bu yüzden paket varsayılan ağ geçidine, yani evdeki yönlendiriciye gitmelidir.",Laptop:"Dizüstü","Local range":"Yerel aralık",Gateway:"Ağ geçidi","Find the Router":"Yönlendiriciyi bul","ARP turns an IP into a MAC":"ARP bir IP’yi MAC’e çevirir","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Yerel ağda çerçeveler MAC adresine göre teslim edilir. Yönlendiricinin MAC adresi dizüstünün ARP önbelleğinde yoksa dizüstü herkese “192.168.1.1 kimde?” diye yayın yapar ve yönlendirici MAC adresiyle yanıt verir.",Asks:"Sorar","Who has 192.168.1.1?":"192.168.1.1 kimde?","Sent to":"Alıcı","Everyone (broadcast)":"Herkes (yayın)",Learns:"Öğrenir","Router’s MAC address":"Yönlendiricinin MAC adresi","who has 192.168.1.1?":"192.168.1.1 kimde?","tell 192.168.1.10":"192.168.1.10’a bildir","Send the Packet":"Paketi gönder","Addresses, TTL and protocol":"Adresler, TTL ve protokol","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"IP başlığı kaynak ve hedef adresleri, bir TTL’yi ve içindeki protokolü taşır. Burada 443 numaralı porta giden bir TCP SYN içerir. Windows TTL’yi 128’den başlatır (Linux ve macOS 64 kullanır).","From → to":"Kimden → kime","TTL 128 · protocol TCP":"TTL 128 · protokol TCP","NAT, Then Hop by Hop":"NAT, sonra atlama atlama","The router rewrites and forwards":"Yönlendirici yeniden yazar ve iletir","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Yönlendirici özel kaynağı kendi genel adresi 198.51.100.7 ile değiştirir (burada 52344 numaralı portu da 40112 ile), eşlemeyi not eder ve TTL’yi 127’ye düşürür. Ardından internetteki 11 yönlendiricinin her biri hedefe göre bir sonraki atlamayı seçer ve TTL’yi yeniden düşürür.","New source":"Yeni kaynak","Leaves home":"Evden çıkar","At the server":"Sunucuda","TTL 116 (11 more hops)":"TTL 116 (11 atlama daha)","TTL 127 · after NAT":"TTL 127 · NAT’tan sonra","The Reply Comes Back":"Yanıt geri gelir","NAT translates it for the laptop":"NAT onu dizüstü için çevirir","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Sunucu, gördüğü adrese, 198.51.100.7:40112’ye yanıt verir. Yönlendirici bunu NAT tablosunda arar, hedefi yeniden 192.168.1.10:52344 olarak yazar ve iletir. Yanıt TTL 64 ile yola çıktı ve 52 ile ulaşır.","Delivered to":"Teslim edilen","TTL 52 · after NAT":"TTL 52 · NAT’tan sonra","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (NAT’tan sonra)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (NAT’tan sonra)","ARP request · 28 bytes":"ARP isteği · 28 bayt","Broadcast: every device on the network receives it.":"Yayın: ağdaki her cihaz onu alır.","The sender’s network card.":"Gönderenin ağ kartı.","Hardware type":"Donanım türü","Protocol type":"Protokol türü","Address sizes":"Adres boyutları",Operation:"İşlem","1 (request: who has …?)":"1 (istek: … kimde?)","Sender MAC":"Gönderen MAC","Sender IP":"Gönderen IP","Target MAC":"Hedef MAC","All zeros: this is what the request wants to find out.":"Tamamen sıfır: isteğin öğrenmek istediği budur.","Target IP":"Hedef IP","ARP reply · 28 bytes":"ARP yanıtı · 28 bayt","Straight back to the device that asked.":"Doğrudan soran cihaza geri.","2 (reply: … is at …)":"2 (yanıt: … şurada: …)","Seen as it leaves the router’s internet side":"Yönlendiricinin internet tarafından çıkarken görüldüğü hâliyle","The internet provider’s router, the next hop.":"İnternet sağlayıcısının yönlendiricisi, bir sonraki atlama.","The router’s internet-facing port.":"Yönlendiricinin internete bakan portu.","As sent: this system starts at 64.":"Gönderildiği hâliyle: bu sistem 64’ten başlar.","The router’s NAT swapped in its own port for the laptop’s.":"Yönlendiricinin NAT’ı, dizüstünün portu yerine kendi portunu koydu.","The sender’s next router; each hop puts the packet in a new frame.":"Gönderenin bir sonraki yönlendiricisi; her atlamada paket yeni bir çerçeveye konur.","Name Resolution":"Ad çözümleme",Query:"Sorgu",Referral:"Yönlendirme","DNSSEC not requested here":"DNSSEC burada istenmiyor","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"DNS, www.example.com gibi adları bilgisayarların birbirine ulaşmak için kullandığı IP adreslerine çevirir. Hiçbir sunucu tüm adları bilmez: sistem bir sunucular hiyerarşisidir ve yanıtlar yol boyunca önbelleğe alınır; bu yüzden çoğu sorgu hiçbir zaman uzağa gitmek zorunda kalmaz.","53, UDP (TCP if large)":"53, UDP (büyükse TCP)",Turns:"Çevirir","Names into IP addresses":"Adları IP adreslerine",Hierarchy:"Hiyerarşi","Root → TLD → authoritative":"Kök → TLD → yetkili",Caching:"Önbellek","For each record’s TTL":"Her kaydın TTL’si boyunca","Name resolved":"Ad çözümlendi","And remembered for an hour":"Ve bir saat boyunca hatırlandı","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Boş bir önbellekle başlayan çözümleyici kökten .com’a, oradan example.com’un kendi sunucusuna gitti ve sonra dizüstüne yanıt verdi. TTL dolana kadar bu ad için yapılan bir sonraki sorgu doğrudan bir önbellekten yanıtlanır. Yeniden izlemek için TEKRARLA’ya basın.",Queries:"Sorgular","4 (laptop 1, resolver 3)":"4 (dizüstü 1, çözümleyici 3)","Cached for":"Önbellek süresi","Ask the Resolver":"Çözümleyiciye sor","The laptop hands the question off":"Dizüstü soruyu devreder","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Tarayıcının www.example.com’un IP adresine ihtiyacı var ve ne tarayıcının ne de Windows’un önbelleğinde bu adres var. Dizüstü, kendisine verilen özyinelemeli çözümleyiciye, 8.8.8.8’e tek bir soru gönderir ve tüm sorgulamayı onun yapmasını ister (özyineleme isteniyor).","www.example.com, type A":"www.example.com, tür A",Asked:"Sorulan","8.8.8.8 (recursive)":"8.8.8.8 (özyinelemeli)","RD (recursion desired)":"RD (özyineleme isteniyor)","flags: RD":"bayraklar: RD","Points the way to .com":".com’a giden yolu gösterir","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"Çözümleyicinin önbelleği boş (yeni başladı), bu yüzden en tepeden başlar. Bir kök sunucu adresi bilmez, ama .com’dan hangi sunucuların sorumlu olduğunu bilir ve bir yönlendirmeyle yanıt verir. Birçok çözümleyici ona tam adı değil, yalnızca “com” bölümünü gönderir.","Root servers":"Kök sunucular","13 names, 1,000+ anycast sites":"13 ad, 1,000’den fazla anycast konumu","Referral (13 .com servers)":"Yönlendirme (13 .com sunucusu)","no answer: ask .com":"yanıt yok: .com’a sorun","Points the way to example.com":"example.com’a giden yolu gösterir","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Çözümleyici .com sunucularından birine sorar. Onlar da her sitenin adresini tutmaz, ama her .com alan adının hangi ad sunucularını kullandığını bilir; bu yüzden bu yanıt, o sunucuların adresleri (glue) eklenmiş başka bir yönlendirmedir.",Knows:"Bilir","Name servers of .com domains":".com alan adlarının ad sunucuları","Referral + glue addresses":"Yönlendirme + glue adresleri","no answer: ask example.com":"yanıt yok: example.com’a sorun","Gives the actual answer":"Asıl yanıtı verir","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Sonunda çözümleyici, alan adının kayıtlarını tutan example.com’un kendi ad sunucusuna sorar. Sunucu A kaydıyla yanıt verir ve yanıtı yetkili olarak işaretler. Ne kadar süre önbellekte tutulabileceğini alan adının sahibi belirler: burada 3600 saniye.","AA (authoritative), TTL 3600":"AA (yetkili), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · AA bayrağı","Answer & Cache":"Yanıt ve önbellek","The laptop gets its address":"Dizüstü adresini alır","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Çözümleyici yanıtı dizüstüne geri gönderir ve bir kopyasını saklar. Sonraki bir saat boyunca bu adı anında yanıtlayabilir; HTTP dersindeki sorgunun yalnızca 24 ms sürmesinin nedeni budur. Dizüstü de onu önbelleğe alır.","RD, RA (recursion available)":"RD, RA (özyineleme kullanılabilir)","Cached by":"Önbelleğe alan","Resolver and laptop":"Çözümleyici ve dizüstü","flags: RD RA":"bayraklar: RD RA","Referral: com. NS ×13 (with glue)":"Yönlendirme: com. NS ×13 (glue ile)","Referral: example.com. NS ×2 (with glue)":"Yönlendirme: example.com. NS ×2 (glue ile)","Response A 203.0.113.10 (authoritative)":"Yanıt A 203.0.113.10 (yetkili)","As sent: this system starts at 128.":"Gönderildiği hâliyle: bu sistem 128’den başlar.","0x0000: query":"0x0000: sorgu","UDP size 1232, DNSSEC OK = 0":"UDP boyutu 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Bir UDP yanıtının ne kadar büyük olabileceğini söyler. Dersi kısa tutmak için burada DNSSEC imzaları istenmiyor; 8.8.8.8 gibi doğrulama yapan bir çözümleyici bunları ister.","0x8000: response":"0x8000: yanıt",Authority:"Yetki",Additional:"Ek","0x8400: response, AA (authoritative)":"0x8400: yanıt, AA (yetkili)","Getting an Address":"Adres almak","From the laptop":"Dizüstünden","From the DHCP server":"DHCP sunucusundan","Dynamic Host Configuration Protocol":"Dinamik ana bilgisayar yapılandırma protokolü","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP bir cihaza ağı kullanmak için gereken her şeyi verir: bir IP adresi, alt ağ maskesi, trafiğin üzerinden gönderileceği yönlendirici ve sorulacak DNS sunucuları. Adresler belirli bir süre için kiralanır ve cihaz ağda kaldıkça yenilenir.","UDP 67 (server), 68 (client)":"UDP 67 (sunucu), 68 (istemci)","Hands out":"Dağıtır","IP, mask, gateway, DNS":"IP, maske, ağ geçidi, DNS",Exchange:"Alışveriş",Lease:"Kira","Renewed at half its time":"Süresinin yarısında yenilenir","On the network":"Ağda","Leased, and kept up to date":"Kiralandı ve güncel tutuluyor","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Dört mesaj, dizüstünü adressiz hâlden çalışan bir yapılandırmaya taşıdı; 24 saatlik kiranın yarısında da dizüstü kirayı yönlendiriciye doğrudan bir istekle yeniledi. Yeniden izlemek için TEKRARLA’ya basın.",Messages:"Mesajlar","4 to join, 2 per renewal":"Katılmak için 4, her yenilemede 2","24 h, renewed at 12 h":"24 sa, 12 sa’te yenilenir","No Address Yet":"Henüz adres yok","The laptop joins the network":"Dizüstü ağa katılır","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"Dizüstü az önce bağlandı. Yerleşik bir MAC adresi var, ama IP adresi, ağ geçidi ve DNS sunucusu yok; bu yüzden henüz kendi ağının ötesindeki hiçbir şeyle konuşamaz. Bunları DHCP ile ister.","IP address":"IP adresi","None (uses 0.0.0.0)":"Yok (0.0.0.0 kullanır)","MAC address":"MAC adresi",Needs:"İhtiyacı",Discover:"Keşif","Shout to the whole network":"Tüm ağa seslen","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Kendine ait bir adresi olmadığından dizüstü, 0.0.0.0’dan 255.255.255.255 yayın adresine gönderir; böylece yerel ağdaki her cihaz bunu alır. Yalnızca DHCP sunucuları yanıt verir.",From:"Kimden","0.0.0.0, UDP port 68":"0.0.0.0, UDP portu 68","255.255.255.255, port 67":"255.255.255.255, port 67",Carries:"Taşıdığı","MAC, transaction ID":"MAC, işlem kimliği","any DHCP server out there?":"orada bir DHCP sunucusu var mı?",Offer:"Teklif","The router proposes an address":"Yönlendirici bir adres önerir","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"Yönlendiricinin DHCP sunucusu boş bir adres seçer ve diğer ayarlarla birlikte teklif eder. Dizüstü henüz bir IP adresi kullanamaz, bu yüzden teklif doğrudan onun MAC adresine gider (bazı istemciler bunun yerine yayın ister).",Offered:"Teklif edilen","Gateway, DNS":"Ağ geçidi, DNS","offer: 192.168.1.10/24":"teklif: 192.168.1.10/24","gateway, DNS, lease 24 h":"ağ geçidi, DNS, kira 24 sa","Accept, out loud":"Herkesin önünde kabul","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"Dizüstü, seçtiği sunucunun adını vererek teklif edilen adresi ister. Hâlâ yayın yapar; böylece teklif vermiş başka bir DHCP sunucusu seçilmediğini öğrenir ve adresini serbest bırakabilir.",Requests:"İstediği","Chosen server":"Seçilen sunucu","I’ll take 192.168.1.10":"192.168.1.10’u alıyorum","from server 192.168.1.1":"192.168.1.1 sunucusundan",Acknowledge:"Onay","The address is the laptop’s":"Adres artık dizüstünün","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Sunucu onaylar ve dizüstü adresini, maskesini, ağ geçidini ve DNS sunucusunu ayarlar. Birçok sistem önce ARP ile adresi başka bir cihazın kullanmadığını kontrol eder.","DNS server":"DNS sunucusu","192.168.1.10 is yours":"192.168.1.10 sizin","for 24 hours":"24 saat boyunca",Renew:"Yenileme","Halfway through the lease":"Kira süresinin yarısında","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"On iki saat sonra kira süresinin yarısı doldu. Dizüstünün artık bir adresi olduğundan kirayı uzatmasını doğrudan yönlendiriciden ister ve yönlendirici kirayı yeniden 24 saate ayarlar. Yönlendirici yanıt vermeseydi %87.5’te yayın yapardı.",When:"Ne zaman","50% of lease (T1 = 12 h)":"Kiranın %50’si (T1 = 12 sa)","The router (unicast)":"Yönlendirici (tekil yayın)","If unanswered":"Yanıt gelmezse","Broadcast at 87.5% (T2)":"%87.5’te yayın (T2)","renew 192.168.1.10":"192.168.1.10’u yenile","sent straight to 192.168.1.1":"doğrudan 192.168.1.1’e gönderildi","lease renewed":"kira yenilendi","another 24 hours":"24 saat daha",Message:"Mesaj","1 (request, from a client)":"1 (istek, istemciden)",Hardware:"Donanım","Ethernet, 6-byte addresses":"Ethernet, 6 baytlık adresler",Hops:"Atlamalar","Chosen by the client; every reply repeats it.":"İstemci seçer; her yanıt bunu tekrarlar.",Seconds:"Saniye","0x0000 (unicast replies are fine)":"0x0000 (tekil yanıtlar uygundur)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Yayın bayrağı kapalı: sunucu doğrudan istemcinin MAC adresine gönderebilir.","Client address":"İstemci adresi","Filled in only when the client already has an address (renewing).":"Yalnızca istemcinin zaten bir adresi varsa (yenileme) doldurulur.","Your address":"Sizin adresiniz","The address the server is giving out.":"Sunucunun dağıttığı adres.","Next server":"Sonraki sunucu","Relay agent":"Aktarma aracısı","Client MAC":"İstemci MAC","Server name, boot file":"Sunucu adı, önyükleme dosyası",empty:"boş","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Ardından gelen seçeneklerin DHCP olduğunu belirtir.","Message type: 1 (Discover)":"Mesaj türü: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"İstemci kimliği: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Ana bilgisayar adı: alice-laptop","Vendor class: MSFT 5.0":"Üretici sınıfı: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"İstenen parametreler: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (yanıt, sunucudan)","Message type: 2 (Offer)":"Mesaj türü: 2 (Offer)","Server identifier: 192.168.1.1":"Sunucu kimliği: 192.168.1.1","Lease time: 86,400 s (24 h)":"Kira süresi: 86,400 sn (24 sa)","Renewal time (T1): 43,200 s (12 h)":"Yenileme süresi (T1): 43,200 sn (12 sa)","Rebinding time (T2): 75,600 s (21 h)":"Yeniden bağlama süresi (T2): 75,600 sn (21 sa)","Subnet mask: 255.255.255.0":"Alt ağ maskesi: 255.255.255.0","Broadcast address: 192.168.1.255":"Yayın adresi: 192.168.1.255","DNS server: 8.8.8.8":"DNS sunucusu: 8.8.8.8","Message type: 3 (Request)":"Mesaj türü: 3 (Request)","Requested address: 192.168.1.10":"İstenen adres: 192.168.1.10","Client FQDN: alice-laptop":"İstemci FQDN: alice-laptop","Message type: 5 (ACK)":"Mesaj türü: 5 (ACK)","Network Diagnostics":"Ağ tanılama","Ping / probe":"Ping / yoklama","Echo reply":"Yankı yanıtı","Error report":"Hata bildirimi","Internet Control Message Protocol":"İnternet denetim mesajı protokolü","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP, ağın geri bildirim verme yoludur: bir yönlendirici bir paketin süresinin dolduğunu, bir sunucu bir portu hiçbir şeyin dinlemediğini bildirir. ping ve traceroute gibi araçlar bu mesajlardan oluşur. IP’nin içinde taşınır ama uygulama verisi taşımaz.","Carried in":"Taşındığı yer","IP (protocol 1)":"IP (protokol 1)","A type and a code":"Bir tür ve bir kod",Tools:"Araçlar",Often:"Çoğu zaman","Filtered by firewalls":"Güvenlik duvarlarınca filtrelenir","The network answered":"Ağ yanıt verdi","Replies, expiries and errors":"Yanıtlar, süre dolumları ve hatalar","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Bir yankı isteği gidiş-dönüş süresini ölçtü, küçük TTL’li paketler yol üzerindeki her yönlendiricinin kendini tanıtmasını sağladı ve kapalı bir port hemen geri bildirildi. Yeniden izlemek için TEKRARLA’ya basın.","Round trip":"Gidiş-dönüş",Path:"Yol","12 routers, server at hop 13":"12 yönlendirici, sunucu 13. atlamada","Types used":"Kullanılan türler","8, 0, 11 and 3":"8, 0, 11 ve 3","Reply TTL":"Yanıt TTL’si",Ping:"Ping","Echo request":"Yankı isteği","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"“ping -n 1 203.0.113.10” tek bir ICMP yankı isteği gönderir (düz ping, saniyede bir olmak üzere dört tane gönderir): tür 8, kod 0; bir tanımlayıcı, bir sıra numarası ve 32 baytlık dolgu içerir. Sunucunun sistemi kendiliğinden yanıt verir, bir uygulamaya gerek yoktur.","Type, code":"Tür, kod","8, 0 (echo request)":"8, 0 (yankı isteği)","type 8 · seq 1":"tür 8 · sıra 1","32 bytes of data":"32 bayt veri","Echo Reply":"Yankı yanıtı","Round-trip time":"Gidiş-dönüş süresi","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Sunucu aynı tanımlayıcı, sıra numarası ve veriyle tür 0 olan bir yankı yanıtı geri gönderir. Ping geçen süreyi ve yanıtın hangi TTL ile ulaştığını yazdırır: “bytes=32 time=34ms TTL=52”.","0, 0 (echo reply)":"0, 0 (yankı yanıtı)","TTL on arrival":"Varıştaki TTL","type 0 · seq 1":"tür 0 · sıra 1","same 32 bytes back":"aynı 32 bayt geri gelir","The first router answers":"İlk yönlendirici yanıt verir","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"“ping -n 1 -i 1” aynı isteği TTL 1 ile gönderir. Ev yönlendiricisi onu 0’a düşürür; bu yüzden paketi atmak zorundadır ve kendi adresinden bir Süre Aşıldı (Time Exceeded) mesajı geri gönderir: “Reply from 192.168.1.1: TTL expired in transit.”","Sent with":"Gönderildiği TTL","Dropped by":"Atan","11, 0 (time exceeded)":"11, 0 (süre aşıldı)","echo request":"yankı isteği","expires at the first router":"ilk yönlendiricide süresi dolar","type 11 · from 192.168.1.1":"tür 11 · 192.168.1.1’den","quotes the dropped header":"atılan başlığı alıntılar","The next router answers":"Sonraki yönlendirici yanıt verir","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"“-i 2” ile ev yönlendiricisi TTL’yi 1’e düşürüp iletir. İnternet sağlayıcısındaki ilk yönlendirici onu 0’a düşürür ve 198.51.100.1’den geri bildirir. Ev yönlendiricisi bu bildirimi, her yanıtta olduğu gibi dizüstü için geri çevirir.","ISP router 198.51.100.1":"Sağlayıcı yönlendiricisi 198.51.100.1","expires at the second router":"ikinci yönlendiricide süresi dolar","type 11 · from 198.51.100.1":"tür 11 · 198.51.100.1’den","That’s Traceroute":"İşte traceroute","TTL 1, 2, 3 … until it arrives":"Ulaşana kadar TTL 1, 2, 3 …","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert bunu otomatikleştirir: TTL’yi her seferinde bir artırır, her atlama için üç yoklama gönderir ve kimin yanıt verdiğini listeler. 3’ten 12’ye kadar olan atlamalar aynı şekilde çalışır ve TTL 13 ile istek sonunda sunucuya ulaşır; sunucu normal şekilde yanıt verir.","12 routers, then the server":"12 yönlendirici, sonra sunucu","Per hop":"Atlama başına","3 probes":"3 yoklama","On Linux":"Linux’ta","traceroute sends UDP":"traceroute UDP gönderir","enough hops to arrive":"ulaşmaya yetecek kadar atlama","the server itself answers":"sunucunun kendisi yanıt verir","end of the route":"rotanın sonu",Unreachable:"Ulaşılamıyor","Nothing listening on that port":"O portu hiçbir şey dinlemiyor","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Bir uygulama, hiçbir şeyin dinlemediği 9999 numaralı porta bir UDP datagramı gönderir. Sunucu onu teslim edemez, bu yüzden datagramın başını alıntılayarak Hedefe Ulaşılamıyor, kod 3 (porta ulaşılamıyor) ile yanıt verir. Birçok güvenlik duvarı bu tür paketleri bunun yerine sessizce atar.","3, 3 (port unreachable)":"3, 3 (porta ulaşılamıyor)","Other codes":"Diğer kodlar","0 net, 1 host, 4 too big":"0 ağ, 1 ana bilgisayar, 4 fazla büyük",Firewalls:"Güvenlik duvarları","Often silent instead":"Çoğu zaman sessiz kalır","to port 9999":"9999 numaralı porta","nothing listening there":"orada dinleyen yok","type 3 · code 3":"tür 3 · kod 3","port unreachable":"porta ulaşılamıyor","ICMP · Echo request":"ICMP · Yankı isteği",Code:"Kod","Covers the whole ICMP message.":"ICMP mesajının tamamını kapsar.",Identifier:"Tanımlayıcı","Matches replies to this ping program.":"Yanıtları bu ping programıyla eşleştirir.","Windows counts up across every ping it sends.":"Windows gönderdiği tüm ping’ler boyunca sayar.","Windows ping’s filler: the alphabet, a to w, then again.":"Windows ping’inin dolgusu: a’dan w’ye alfabe, sonra yeniden.","ICMP · Echo reply":"ICMP · Yankı yanıtı","Sent back exactly as it came.":"Geldiği gibi aynen geri gönderilir.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Süre aşıldı (TTL 0’a ulaştı)","Time exceeded (TTL reached 0)":"Süre aşıldı (TTL 0’a ulaştı)",Unused:"Kullanılmıyor","Original packet":"Orijinal paket","Its source, destination":"Kaynağı, hedefi","its IP header and first 8 bytes (28 bytes)":"IP başlığı ve ilk 8 baytı (28 bayt)","App data":"Uygulama verisi","What the app sent; nothing on the server is listening for it.":"Uygulamanın gönderdiği; sunucuda onu bekleyen hiçbir şey yok.","ICMP · Destination unreachable (port unreachable)":"ICMP · Hedefe ulaşılamıyor (porta ulaşılamıyor)","Destination unreachable (port unreachable)":"Hedefe ulaşılamıyor (porta ulaşılamıyor)","Sending Email":"E-posta göndermek","SMTP command":"SMTP komutu","SMTP reply":"SMTP yanıtı","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP e-postaları taşır: e-posta uygulamanızdan sağlayıcınızın sunucusuna, o sunucudan da alıcınınkine. Kısa metin komutlarından oluşan bir konuşmadır; her komut üç haneli bir yanıt koduyla karşılanır. Posta okumak ayrı bir iştir ve IMAP ya da POP3 ile yapılır.","465/587 submit, 25 relay":"465/587 gönderim, 25 aktarma","TCP, usually with TLS":"TCP, genellikle TLS ile",Commands:"Komutlar",Replies:"Yanıtlar","2xx ok, 3xx go on, 4/5xx error":"2xx tamam, 3xx devam, 4/5xx hata","Mail delivered":"Posta teslim edildi","Two hops, one message":"İki atlama, bir mesaj","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"Alice’in uygulaması mesajı şifreli ve oturum açılmış bir bağlantı üzerinden sağlayıcısına teslim etti. Sağlayıcı Bob’un posta sunucusunu DNS’te buldu ve mesajı oraya aktardı, bu bağlantıyı da TLS’ye yükseltti. Mesaj şimdi Bob onu IMAP ya da POP3 ile okuyana kadar onun posta kutusunda bekliyor.","Laptop → provider → Bob’s":"Dizüstü → sağlayıcı → Bob’unki",Submission:"Gönderim","Port 465, TLS, login":"Port 465, TLS, oturum açma",Relay:"Aktarma","Port 25, STARTTLS":"Port 25, STARTTLS","Checks at Bob’s":"Bob tarafındaki denetimler","Connect Securely":"Güvenli bağlan","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice Gönder’e basar. E-posta uygulaması, sağlayıcısının gönderim sunucusu smtp.example.com’a 465 numaralı porttan bağlanır. Bu portta TLS hemen başlar; böylece parolası dahil tüm SMTP konuşması şifrelenir.","TLS from the start":"Baştan TLS","SMTP inside TLS":"TLS içinde SMTP","Greeting & Login":"Karşılama ve oturum açma","EHLO, then AUTH":"EHLO, sonra AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Sunucu 220 koduyla selam verir. Uygulama EHLO der ve sunucu, AUTH dahil desteklediklerini listeler. Uygulama AUTH PLAIN ile (kullanıcı adı ve parola, base64 ile kodlanmış) oturum açar ve 235 alır: kimlik doğrulandı.",Greeting:"Karşılama",Capabilities:"Yetenekler","Login result":"Oturum açma sonucu","user and password, base64":"kullanıcı ve parola, base64","Send the Message":"Mesajı gönder","Envelope, then content":"Önce zarf, sonra içerik","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM ve RCPT TO zarftır: gönderen ve alıcı. PIPELINING üç komutun tek bir paketi paylaşmasını sağlar. 354’ten sonra mesaj gelir ve yalnızca bir nokta içeren bir satırla biter.",Envelope:"Zarf","Content ends":"İçeriğin sonu","A line with only “.”":"Yalnızca “.” olan bir satır",Result:"Sonuç","… message …":"… mesaj …","Find Bob’s Server":"Bob’un sunucusunu bul","An MX lookup in DNS":"DNS’te bir MX sorgusu","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Alice’in sağlayıcısı şimdi example.org’a teslim etmek zorunda. DNS’ten bu alan adının, postasını kabul eden sunucuyu belirten MX kaydını ister, sonra o sunucunun adresini sorgular.","MX record":"MX kaydı","Asked by":"Soran","Alice’s provider":"Alice’in sağlayıcısı","Server to Server":"Sunucudan sunucuya","Port 25, upgraded with STARTTLS":"Port 25, STARTTLS ile yükseltilir","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Sağlayıcı mx.example.org’a 25 numaralı porttan bağlanır. Bu konuşma düz metinle başlar: karşılama ve EHLO yanıtı STARTTLS’i duyurur, sağlayıcı bunu ister, 220 alır ve iki taraf da TLS’ye geçer.","Starts as":"Başlangıçta","Plain text":"Düz metin",Upgrade:"Yükseltme",Deliver:"Teslim et","The same transaction again":"Aynı işlem yeniden","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"TLS açıkken sağlayıcı EHLO’yu, ardından zarfı ve mesajı yineler; mesaja artık bir DKIM imzası ve bir Received başlığı eklenmiştir. Bob’un sunucusu SPF, DKIM ve DMARC denetimlerini yapar ve mesajı kabul eder.","Login needed":"Oturum açma gerekir mi","No (server to server)":"Hayır (sunucudan sunucuya)","1,316 bytes (signed)":"1,316 bayt (imzalı)","Server Hello + encrypted handshake, 2 segments":"Server Hello + şifreli el sıkışma, 2 segment","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 yetenekler (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (kimlik bilgileri)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (art arda)","Message (316 bytes), then “.”":"Mesaj (316 bayt), sonra “.”","250 capabilities (PIPELINING, STARTTLS …)":"250 yetenekler (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 yetenekler (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Mesaj (1,316 bayt), sonra “.”","What this client supports. Its exact contents vary from client to client; this is an example.":"Bu istemcinin destekledikleri. Tam içerik istemciden istemciye değişir; bu bir örnektir.","up to 512 bytes":"en fazla 512 bayt","The server’s choices and its key share.":"Sunucunun seçimleri ve anahtar payı.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (zincir), Certificate Verify (imza), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Alice’in mesajı (316 bayt), sonra yalnızca “.” içeren bir satır","example.org, type MX, class IN":"example.org, tür MX, sınıf IN","mx.example.org, type A, class IN":"mx.example.org, tür A, sınıf IN",Timestamps:"Zaman damgaları","Used to measure round trips; both sides offered them.":"Gidiş-dönüş sürelerini ölçmek için kullanılır; iki taraf da bunları önerdi.","The signed message (1,316 bytes), then a line holding only “.”":"İmzalı mesaj (1,316 bayt), sonra yalnızca “.” içeren bir satır","Downloading Email":"E-posta indirmek","POP3 command":"POP3 komutu","POP3 reply":"POP3 yanıtı","Post Office Protocol, version 3":"Postane protokolü, sürüm 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"POP3, bir e-posta uygulamasının bir sunucudaki posta kutusundan mesajları indirmesini sağlar. Postayı çekip ardından sunucudan silen tek bir cihaz için tasarlanmıştır. Komutlar kısa kelimelerdir ve her yanıt +OK ya da -ERR ile başlar.",Model:"Model","Download, then delete":"İndir, sonra sil","Mail downloaded":"Posta indirildi","And gone from the server":"Ve sunucudan gitti","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"Bob’un uygulaması oturum açtı, iki mesaj gördü, ilkini indirip sildi; sunucu silme işlemini QUIT gelince yaptı. O mesaj artık yalnızca bu dizüstünde duruyor; POP3’ün tek cihaza, IMAP’in birden çok cihaza uygun olmasının nedeni budur.","2 waiting, 1 downloaded":"2 bekliyor, 1 indirildi",Deleted:"Silindi","At QUIT (UPDATE state)":"QUIT gelince (UPDATE durumu)","Best for":"En uygun olduğu","A single device":"Tek bir cihaz","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"Bob’un e-posta uygulaması pop.example.org’a 995 numaralı porttan bağlanır; bu portta TLS hemen başlar. Onun içinde sunucu +OK ile selam verir. (110 numaralı portta oturum düz metinle başlar ve STLS komutuyla yükseltilir.)","USER, then PASS":"USER, sonra PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"Uygulama kullanıcı adını USER ile, parolayı PASS ile gönderir. Her komut kendi +OK yanıtını alır. Oturum TLS içinde olduğundan parola yolda okunamaz.","Protected by":"Koruyan","Check the Mailbox":"Posta kutusunu kontrol et","STAT and LIST":"STAT ve LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT, mesaj sayısını ve toplam boyutu döndürür: 2 mesaj, 5120 bayt. LIST her mesajın numarasını ve boyutunu verir ve yalnızca bir nokta içeren bir satırla biter.","Message 1":"Mesaj 1","Message 2":"Mesaj 2",Download:"İndir","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 ilk mesajı ister. Sunucu boyutuyla birlikte +OK yanıtı verir, ardından mesajı ve kapanış noktasını gönderir: 1904 bayt artı yanıt satırı, iki TCP segmenti.",Command:"Komut","Delete & Quit":"Sil ve çık","Deleted only at QUIT":"Yalnızca QUIT gelince silinir","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 mesajı yalnızca işaretler. Sunucu onu, uygulama QUIT dediğinde kaldırır: bağlantı daha önce koparsa hiçbir şey silinmez. Birçok uygulama DELE’yi atlayan “sunucuda bir kopya bırak” seçeneği sunar.","Marks message 1":"Mesaj 1’i işaretler",Removed:"Kaldırıldı",Option:"Seçenek","Leave a copy on server":"Sunucuda bir kopya bırak","PASS (password)":"PASS (parola)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, mesaj, “.” (2 segment)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, 1,904 baytlık mesaj, sonra yalnızca “.” içeren bir satır","Mail That Stays in Sync":"Senkronize kalan posta","IMAP command":"IMAP komutu","IMAP response":"IMAP yanıtı","Internet Message Access Protocol":"İnternet mesaj erişim protokolü","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"IMAP, e-posta uygulamalarının sunucuda kalan bir posta kutusuyla çalışmasını sağlar. Klasörler, okundu ve bayraklı işaretleri ve silmeler orada tutulur; böylece telefon, dizüstü ve web postası aynı posta kutusunu görür. Sunucu, yeni posta geldiği anda bunu uygulamaya da bildirebilir.","Mail stays on the server":"Posta sunucuda kalır",Syncs:"Senkronize eder","Folders and flags":"Klasörler ve bayraklar","Mailbox in sync":"Posta kutusu senkronize","Read once, read everywhere":"Bir kez okundu, her yerde okundu","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"Bob’un uygulaması gelen kutusunu açtı ve bir mesajı okudu; bu, mesajı sunucuda Bob’un tüm cihazları için \\Seen olarak işaretledi. Sonra sunucu yeni posta bildirene kadar IDLE ile bekledi. Hiçbir şey silinmedi: sunucu hâlâ her şeyi tutuyor.","2, then 3 (new mail)":"2, sonra 3 (yeni posta)","Read mark":"Okundu işareti","\\Seen, stored on server":"\\Seen, sunucuda saklanır","New mail":"Yeni posta","Pushed during IDLE":"IDLE sırasında iletilir","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"Bob’un uygulaması imap.example.org’a 993 numaralı porttan bağlanır; bu portta TLS hemen başlar. Sunucu, IDLE gibi yeteneklerini de listeleyen etiketsiz bir “* OK” satırıyla selam verir.","Commands carry tags":"Komutlar etiket taşır","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Her komut, uygulamanın seçtiği a1 gibi bir etiketle başlar ve sunucu yanıtını aynı etiketle bitirir. Böylece birden çok komut aynı anda yolda olabilir ve her yanıt doğru komutla eşleşir. * ile başlayan satırlar etiketsiz verilerdir.",Tags:"Etiketler","Match replies to commands":"Yanıtları komutlarla eşleştirir","Open the Inbox":"Gelen kutusunu aç","SELECT a folder":"Bir klasörü SELECT ile aç","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX klasörü açar. Sunucu mesaj sayısını, desteklediği bayrakları ve ilk okunmamış mesajı bildirir, ardından klasörün okuma-yazma için açık olduğunu onaylar.","First unread":"İlk okunmamış",Access:"Erişim","Read a Message":"Bir mesajı oku","FETCH, and the \\Seen flag":"FETCH ve \\Seen bayrağı","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] 2. mesajı indirir (üç TCP segmenti). Bu, mesajın sunucudaki \\Seen bayrağını ayarlar; böylece mesaj Bob’un telefonunda da okunmuş görünür ve sunucuda kalmaya devam eder.","Flag set":"Ayarlanan bayrak","\\Seen (on the server)":"\\Seen (sunucuda)","Wait for New Mail":"Yeni postayı bekle","IDLE: the server pushes":"IDLE: sunucu bildirir","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE sunucuya “bir şey değişince bana haber ver” der. Yaklaşık 42 saniye sonra Alice’in mesajı gelir ve sunucu hemen “* 3 EXISTS” gönderir. Uygulama IDLE’ı DONE ile bitirir ve yeni postayı çekebilir.","Server says":"Sunucunun söylediği","* 3 EXISTS (new mail)":"* 3 EXISTS (yeni posta)","Ended by":"Bitiren","a1 LOGIN (user and password)":"a1 LOGIN (kullanıcı ve parola)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, 3,216 baytlık mesaj, sonra a3 OK FETCH completed","Transferring Files":"Dosya aktarmak","FTP command":"FTP komutu","FTP reply":"FTP yanıtı","File data":"Dosya verisi","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP dosyaları bir istemci ile bir sunucu arasında taşır. İki TCP bağlantısı kullanmasıyla alışılmadıktır: biri komutlar ve yanıtlar için, her dosya ya da listeleme için de yeni bir tane. 1970’lerin başından kalmadır ve parolalar dahil her şeyi düz metin olarak gönderir.","21 control, data varies":"21 denetim, veri değişir",Connections:"Bağlantılar","Control + one per transfer":"Denetim + aktarım başına bir",Encryption:"Şifreleme","None (plain text)":"Yok (düz metin)","Safer options":"Daha güvenli seçenekler","File downloaded":"Dosya indirildi","Two connections, no encryption":"İki bağlantı, şifreleme yok","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Komutlar denetim bağlantısından, dosya kendi veri bağlantısından gitti ve o bağlantının kapanması dosyanın sonunu belirtti. Yol üzerindeki herkes parolayı ve dosyayı okuyabilirdi; bugün SFTP ya da FTPS kullanılmasının nedeni budur.","2 (control + data)":"2 (denetim + veri)",File:"Dosya","4,000 bytes, 3 segments":"4,000 bayt, 3 segment",Password:"Parola","Sent in plain text":"Düz metin olarak gönderilir","Use instead":"Bunun yerine","Control Connection":"Denetim bağlantısı","Port 21, plain text":"Port 21, düz metin","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"FTP uygulaması ftp.example.com’a 21 numaralı porttan bir TCP bağlantısı açar. Bu denetim bağlantısı tüm oturumun komutlarını ve yanıtlarını taşır. Sunucu 220 ile selam verir. SMTP’de olduğu gibi her yanıt üç haneli bir kodla başlar.","USER and PASS, readable by anyone":"USER ve PASS, herkes okuyabilir","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"Uygulama USER’ı gönderir, sunucu 331 ile parolayı ister ve PASS onu gönderir. Hiçbir şey şifrelenmez; bu yüzden kullanıcı adı ve parola yol üzerindeki her ağdan okunabilir metin olarak geçer.","Visible to":"Görebilen","Anyone on the path":"Yol üzerindeki herkes","Passive Mode":"Pasif mod","The server names a data port":"Sunucu bir veri portu belirtir","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I bayt bayt ikili bir kopya ister. PASV, sunucudan veri bağlantısı için bir port açmasını ister. Yanıt, adresi ve portu altı sayı olarak kodlar: 195 × 256 + 149 = port 50069. Bağlantıyı dizüstü dışarıya doğru açar; bu NAT üzerinden çalışır.","Data port":"Veri portu","Active mode":"Aktif mod","Server dials in: NAT blocks":"Sunucu içeri bağlanır: NAT engeller","Data Connection":"Veri bağlantısı","A second TCP connection":"İkinci bir TCP bağlantısı","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"Uygulama 50069 numaralı porta ikinci bir TCP bağlantısı açar ve denetim bağlantısında RETR ile dosyayı ister. Sunucu orada 150 ile yanıt verir ve dosyayı yeni bağlantı üzerinden göndermeye başlar.","Data to":"Verinin gittiği yer","The File Arrives":"Dosya ulaşır","Closing the connection ends it":"Bağlantının kapanması sonu belirtir","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"4,000 bayt 3 TCP segmentiyle ulaşır. FTP, verinin içinde uzunluk bilgisi göndermez: sunucu dosyanın sonunu belirtmek için veri bağlantısını kapatır. Dizüstü her şeyi onayladıktan sonra sunucu, denetim bağlantısında 226 ile onaylar.","End of file":"Dosya sonu","Data connection closed":"Veri bağlantısı kapandı","4,000 bytes, readable by anyone":"4,000 bayt, herkes okuyabilir","end of file:":"dosya sonu:","data connection closed":"veri bağlantısı kapandı",Quit:"Çıkış","Close the control connection":"Denetim bağlantısını kapat","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT oturumu bitirir ve sunucu 221 ile veda eder. Hassas her şey için SFTP (SSH üzerinde çalışan farklı bir protokol) ya da FTPS (TLS içinde FTP) aynı işi şifreleyerek yapar.","Encrypted cousins":"Şifreli akrabaları","FTP data":"FTP verisi","The file itself, unencrypted: anyone on the path could read it.":"Dosyanın kendisi, şifresiz: yol üzerindeki herkes okuyabilirdi.","Secure Remote Login":"Güvenli uzaktan oturum açma","Plain setup":"Düz metin kurulum","From laptop":"Dizüstünden","From server":"Sunucudan","Some packets not shown":"Bazı paketler gösterilmiyor","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH size başka bir bilgisayarla şifreli ve kimliği doğrulanmış bir bağlantı sağlar; onunla orada komut çalıştırır, dosya kopyalar (SFTP, scp) ya da başka bağlantıları taşırsınız. Sunucu kim olduğunu bir ana bilgisayar anahtarıyla kanıtlar; siz de kim olduğunuzu bir anahtar çiftiyle ya da parolayla kanıtlarsınız.","Server proves":"Sunucunun kanıtı","Host key (known_hosts)":"Ana bilgisayar anahtarı (known_hosts)","You prove":"Sizin kanıtınız","Key pair or password":"Anahtar çifti ya da parola","Logged in securely":"Güvenle oturum açıldı","Encrypted from the key exchange on":"Anahtar değişiminden itibaren şifreli","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"İki taraf algoritmalarda anlaştı, kuantum sonrası hibrit bir değişimle ortak anahtarlar oluşturdu ve sunucu kimliğini ana bilgisayar anahtarıyla kanıtladı. Alice de kendi kimliğini, dizüstünden hiç çıkmayan bir özel anahtarla imzalayarak kanıtladı, sonra her tuş için bir paket olmak üzere bir komut yazdı.",Login:"Oturum açma","Ed25519 key, no password":"Ed25519 anahtarı, parola yok","Say Hello":"Merhaba de","Versions, in plain text":"Sürümler, düz metinle","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice “ssh alice@server.example.com” komutunu çalıştırır. 22 numaralı porttaki TCP el sıkışmasından sonra her taraf, SSH protokolü sürümünü (2.0) ve yazılımını belirten tek bir düz metin satırı gönderir. SSH’deki geri kalan her şey ikilidir.","Agree on Algorithms":"Algoritmalarda anlaş","KEXINIT lists, first match wins":"KEXINIT listeleri, ilk eşleşme kazanır","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Her taraf, anahtar değişimi, ana bilgisayar anahtarları, şifreleme, bütünlük ve sıkıştırma için desteklediği tüm algoritmaları tercih sırasına göre listeleyen bir KEXINIT gönderir. Her kategoride, dizüstünün listesinde olup sunucunun da desteklediği ilk algoritma seçilir.","Host key":"Ana bilgisayar anahtarı","server’s algorithm lists":"sunucunun algoritma listeleri","in order of preference":"tercih sırasına göre","laptop’s algorithm lists":"dizüstünün algoritma listeleri","Key Exchange":"Anahtar değişimi","Shared keys, and a host key check":"Ortak anahtarlar ve bir ana bilgisayar anahtarı denetimi","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"Dizüstü hibrit bir değişimin kendi yarısını gönderir: gelecekteki kuantum bilgisayarlara dayanması için seçilmiş bir Streamlined NTRU Prime anahtarı ve bir X25519 anahtarı. Sunucu kendi yarısı, ana bilgisayar anahtarı ve değişim üzerine bir imzayla yanıt verir. NEWKEYS şifrelemeyi açar.",Hybrid:"Hibrit","Matches known_hosts":"known_hosts ile eşleşir","First visit":"İlk ziyaret","ssh asks you to confirm":"ssh onaylamanızı ister","public keys":"açık anahtarlar","its half, its host key":"kendi yarısı, ana bilgisayar anahtarı","and a signature":"ve bir imza","Log In with a Key":"Anahtarla oturum aç","Sign, don’t send a secret":"Sır gönderme, imzala","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Sunucu kabul ettiği oturum açma yöntemlerini listeler. Dizüstü Alice’in açık anahtarını önerir ve sunucu bunu kabul edeceğini söyler. Dizüstü ardından bu oturumu, dizüstünden hiç çıkmayan özel anahtarla imzalar. Sunucu imzayı authorized_keys ile denetler.",Methods:"Yöntemler","Ed25519, private stays here":"Ed25519, özel anahtar burada kalır","Checked with":"Denetleyen","alice’s public key":"alice’in açık anahtarı","would you accept it?":"kabul eder misiniz?","yes, that key":"evet, bu anahtar","is in authorized_keys":"authorized_keys içinde","same key, plus a signature":"aynı anahtar, artı bir imza","made with the private key":"özel anahtarla oluşturuldu","logged in":"oturum açıldı","Open a Session":"Bir oturum aç","Channels inside one connection":"Tek bağlantı içinde kanallar","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Tek bir SSH bağlantısı birçok kanal taşıyabilir: bir kabuk, dosya aktarımları, yönlendirilen portlar. Dizüstü bir oturum kanalı açar, sonra bir terminal ve kabuk ister (gösterilmiyor), sunucu da karşılama metnini ve bir komut istemi gönderir.",Channel:"Kanal",session:"oturum","Then asks for":"Sonra istediği","A terminal and a shell":"Bir terminal ve bir kabuk","Also possible":"Ayrıca mümkün","SFTP, port forwarding":"SFTP, port yönlendirme","open a channel:":"kanal aç:","channel open":"kanal açık","Type a Command":"Bir komut yaz","Every key is a packet":"Her tuş bir pakettir","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice pwd yazar. Her tuş hemen kendi şifreli paketiyle çıkar ve sunucu karakteri gösterilmesi için geri gönderir (yankı). OpenSSH 9.5’ten beri tuşları 20 ms’lik bir ritimle gönderir ve sahte paketler ekler; böylece yazma ritmini zamanlamadan çıkarmak zorlaşır.","Per key":"Tuş başına","1 packet, 90 bytes":"1 paket, 90 bayt",Echo:"Yankı","Sent back by the server":"Sunucu geri gönderir",Timing:"Zamanlama","20 ms beat plus decoys":"20 ms ritim ve sahte paketler","Enter key":"Enter tuşu","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Client: KEX_ECDH_INIT (sntrup761x25519 açık anahtarları)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Server: KEX_ECDH_REPLY (ana bilgisayar anahtarı, kendi yarısı, imza)","Encrypted (len=44): service request, ssh-userauth":"Şifreli (len=44): hizmet isteği, ssh-userauth","Encrypted (len=44): service accept":"Şifreli (len=44): hizmet kabul edildi","Encrypted (len=68): login with method none":"Şifreli (len=68): none yöntemiyle oturum açma","Encrypted (len=52): try publickey,password":"Şifreli (len=52): publickey,password deneyin","Encrypted (len=140): offer public key":"Şifreli (len=140): açık anahtar önerir","Encrypted (len=100): public key OK":"Şifreli (len=100): açık anahtar uygun","Encrypted (len=308): public key + signature":"Şifreli (len=308): açık anahtar + imza","Encrypted (len=28): login success":"Şifreli (len=28): oturum açma başarılı","Encrypted (len=52): channel open: session":"Şifreli (len=52): kanal aç: session","Encrypted (len=44): channel open confirmed":"Şifreli (len=44): kanal açılışı onaylandı","Encrypted (len=36): keystroke":"Şifreli (len=36): tuş vuruşu","Encrypted (len=36): echo":"Şifreli (len=36): yankı","Encrypted (len=36): keystroke (Enter)":"Şifreli (len=36): tuş vuruşu (Enter)","Encrypted (len=132): output and a new prompt":"Şifreli (len=132): çıktı ve yeni bir komut istemi","Packet length":"Paket uzunluğu","Bytes after this field.":"Bu alandan sonraki baytlar.","Padding length":"Dolgu uzunluğu","Random padding brings the packet to a multiple of 8 bytes.":"Rastgele dolgu, paketi 8 baytın katına tamamlar.",Cookie:"Cookie","Host keys":"Ana bilgisayar anahtarları","Ciphers, out":"Şifreler, giden","Ciphers, in":"Şifreler, gelen","MACs, out":"MAC’ler, giden","Compression, out":"Sıkıştırma, giden","Compression, in":"Sıkıştırma, gelen","Languages, out":"Diller, giden","Languages, in":"Diller, gelen","First packet follows":"İlk paket ardından gelir",Reserved:"Ayrılmış","Public keys":"Açık anahtarlar","51 bytes: ssh-ed25519 public key":"51 bayt: ssh-ed25519 açık anahtarı","Server’s half":"Sunucunun yarısı","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 bayt (sntrup761 şifreli metni 1,039 + X25519 32)",Signature:"İmza","83 bytes: ssh-ed25519 signature over the exchange":"83 bayt: değişim üzerine ssh-ed25519 imzası","From the next packet on, this side encrypts.":"Bir sonraki paketten itibaren bu taraf şifreler.","SSH · encrypted packet":"SSH · şifreli paket","Encrypted packet":"Şifreli paket","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"chacha20-poly1305 ile uzunluk bile şifrelenir; sondaki 16 baytlık etiket her değişikliği ortaya çıkarır.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): kullanıcı “alice”, hizmet “ssh-connection”, yöntem “none”","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): devam edebilecek yöntemler: “publickey,password”","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): yöntem “publickey”, imza yok, ssh-ed25519 açık anahtarı","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): aynı ssh-ed25519 anahtarı","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): yöntem “publickey-hostbound-v00@openssh.com”, anahtar, sunucunun ana bilgisayar anahtarı ve bir imza","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): “session”, kanal 0, pencere 2 MB, en fazla 32 KB’lık paketler","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): kanal 0 açık","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 bayt, “p”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 bayt, “p”, gösterilmesi için geri gönderildi","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 bayt, “w”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 bayt, “w”, gösterilmesi için geri gönderildi","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 bayt, “d”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 bayt, “d”, gösterilmesi için geri gönderildi","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 bayt, bir satır başı (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 94 bayt: yeni bir satır, kabuğun terminal kodları, “/home/alice” ve renkli komut istemi","Encryption Explained":"Şifreleme açıklandı","From browser":"Tarayıcıdan","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS, TCP’nin üzerine güvenli bir kanal kurar. Sunucunun kimliğini bir sertifikayla kanıtlar, taze anahtarlarda anlaşır, sonra gönderilen her şeyi şifreler ve doğrular. HTTPS, güvenli e-posta ve birçok başka protokol onun içinde çalışır. SSL, öncülünün adıydı.",Sits:"Konumu","Between TCP and the app":"TCP ile uygulama arasında","OSI layer":"OSI katmanı","Often placed at 6":"Genellikle 6’ya yerleştirilir",Current:"Güncel",Retired:"Emekliye ayrılanlar","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 ve 3, TLS 1.0 ve 1.1","The app’s own (443, 993 …)":"Uygulamanın kendi portu (443, 993 …)","Secure from start to finish":"Baştan sona güvenli","One round trip to set up":"Kurulum için tek gidiş-dönüş","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Tek bir gidiş-dönüşle bir sürümde, bir şifrede ve kuantum sonrası hibrit bir anahtarda anlaşıldı. Sertifika zinciri sunucunun kim olduğunu kanıtladı ve Server Hello’dan sonraki her bayt, close_notify’a kadar şifrelendi ve doğrulandı. Yeniden izlemek için TEKRARLA’ya basın.","1 round trip":"1 gidiş-dönüş","Everything the browser supports":"Tarayıcının desteklediği her şey","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"TCP el sıkışmasından sonra tarayıcı neler yapabildiğini listeler: TLS sürümleri, şifre takımları ve beklediği gruplar için anahtar payları; buna kuantum sonrası hibrit X25519MLKEM768 de dahildir. Ayrıca siteyi (SNI) ve konuştuğu protokolleri (ALPN) belirtir.",Versions:"Sürümler","versions, ciphers, key shares":"sürümler, şifreler, anahtar payları","Choices made, keys computed":"Seçimler yapıldı, anahtarlar hesaplandı","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Sunucu TLS 1.3’ü, şifre takımını ve hibrit grubu seçer ve kendi anahtar payını gönderir. İki taraf da iki paydan, ağdan hiç geçmeyen aynı sırrı hesaplar. Bu mesajdan sonraki her şey şifrelidir.",Group:"Grup","From here on":"Buradan itibaren","its key share":"kendi anahtar payı",Certificate:"Sertifika","Who the server is, proven":"Sunucunun kim olduğu kanıtlandı","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Artık şifreli olarak gönderim sürer: seçilen protokol (http/1.1), sertifika zinciri, sertifikanın özel anahtarıyla yapılmış bir imza ve Finished.",Chain:"Zincir","Site → intermediate → root":"Site → ara sertifika → kök","Proves the private key":"Özel anahtarı kanıtlar",Checked:"Denetlenen","Name, dates, trusted root":"Ad, tarihler, güvenilir kök","encrypted: http/1.1, certificates,":"şifreli: http/1.1, sertifikalar,","signature, Finished":"imza, Finished","One round trip, then data":"Tek gidiş-dönüş, sonra veri","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Tarayıcı kendi Finished mesajını gönderir: iki tarafın söylediği her şey üzerine, yeni sırla anahtarlanmış bir denetim değeri; böylece hello mesajlarına yapılan her müdahale ortaya çıkar. TLS 1.3’te veri akmadan önce tek bir gidiş-dönüş gerekir; TLS 1.2’de iki gerekirdi.",Covers:"Kapsadığı","The whole handshake":"El sıkışmanın tamamı","For old middleboxes":"Eski ara cihazlar için","check value over":"şunun üzerine denetim değeri:","the whole handshake":"el sıkışmanın tamamı","Encrypted Data":"Şifreli veri","Records, tags and tickets":"Kayıtlar, etiketler ve biletler","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP artık her biri her değişikliği ortaya çıkaran 16 baytlık bir etiket taşıyan şifreli kayıtlarla yol alır. Sunucu ayrıca iki oturum bileti gönderir: tarayıcı bir dahaki sefere bunlardan biriyle oturumu sürdürüp sertifika adımını atlayabilir.","Per record":"Kayıt başına","22 bytes of overhead":"22 bayt ek yük","2, for resuming later":"2, daha sonra sürdürmek için",Visible:"Görünen","IPs, SNI, sizes, timing":"IP’ler, SNI, boyutlar, zamanlama","2 session tickets":"2 oturum bileti","for resuming later":"daha sonra sürdürmek için",Closing:"Kapanış","close_notify, then TCP":"close_notify, sonra TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"75 saniye boşta kaldıktan sonra sunucu bağlantıyı kapatır. Önce, her şey gibi şifreli bir close_notify uyarısı gönderir; böylece tarayıcı verinin bilerek bittiğini ve bir saldırgan tarafından kesilmediğini anlar. Sonra TCP her zamanki gibi kapanır.",Alert:"Uyarı","Shows nothing was cut off":"Hiçbir şeyin kesilmediğini gösterir","TCP FIN from both sides":"İki taraftan TCP FIN","alert: close_notify":"uyarı: close_notify",encrypted:"şifreli","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ şifreli)","Encrypted handshake (continued)":"Şifreli el sıkışma (devamı)","Encrypted handshake (certificate, verify, Finished)":"Şifreli el sıkışma (sertifika, doğrulama, Finished)","Application Data (inside: close_notify alert)":"Application Data (içinde: close_notify uyarısı)","Alert: close_notify (the data ends here, on purpose)":"Uyarı: close_notify (veri burada, bilerek bitiyor)","No IP address":"IP adresi yok","192.168.1.1 · DHCP server":"192.168.1.1 · DHCP sunucusu"},o={strings:{...i,...n},patterns:[[/^([\d,]+) bytes$/,"$1 bayt"],[/^(Ethernet II|IPv4|UDP|TCP) · (\d+) bytes$/,"$1 · $2 bayt"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,"$1, $2 bayt"],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 bayt: report.pdf, bayt $2"],[/^(.+) h later$/,"$1 sa sonra"],[/^(.+) min later$/,"$1 dk sonra"],[/^(.+) s later$/,"$1 sn sonra"],[/^(\S+) \(relative\)$/,"$1 (göreli)"],[/^(\d+) \(ephemeral\)$/,"$1 (geçici)"],[/^(\d+) TCP segments$/,"$1 TCP segmenti"],[/^(\d+) segments$/,"$1 segment"],[/^(.*), (\d+) segments$/,"$1, $2 segment"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,"TLS 1.3 · $1 kayıt · bayt $2 / $3"],[/^TLS 1\.3 · (\d+) records?$/,"TLS 1.3 · $1 kayıt"],[/^Ethernet padding · (\d+) bytes$/,"Ethernet dolgusu · $1 bayt"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 sıfır bayt, 300 baytlık alt sınıra kadar"],[/^(\d+) zero bytes$/,"$1 sıfır bayt"],[/^(\d+) random bytes$/,"$1 rastgele bayt"],[/^Seen as it leaves (.+)$/,"Şuradan çıkarken görüldü: $1"],[/^Option (\d+)$/,"Seçenek $1"],[/^value (\d+), echo (\d+)$/,"değer $1, yankı $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 bayt, artı $1 bayt seçenek."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows $1 ile başlar. Burada bilerek $2 olarak ayarlandı."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(t,e,a)=>a==="1"?`${e} ile başladı; yoldaki yönlendirici 1 azalttı.`:`${e} ile başladı; yoldaki ${a} yönlendiricinin her biri 1 azalttı.`],[/^all (\d+) bytes of it$/,"$1 baytın tamamı"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Buna yol açan paket, bildiren cihazın aldığı hâliyle (TTL $1); böylece gönderen hangi paket olduğunu anlayabilir."],[/^Port (\d+), TLS from the start$/,"Port $1, baştan TLS"],[/^(\d+), TLS from the start$/,"$1, baştan TLS"]],post:r};export{o as default};
